import 'package:flutter/material.dart';import 'package:flutter_bloc/flutter_bloc.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import '../../../../../../Config/app_config.dart';import '../../../../../../Core/Resources/app_colors.dart';import '../../../../../../Core/Resources/app_fonts.dart';import '../../../../../Global/Authentication/presentation/components/build_social_login_button.dart';import '../Manager/product_details_cubit.dart';class BuildButtonAddCart extends StatelessWidget {  const BuildButtonAddCart({    super.key,  });  @override  Widget build(BuildContext context) {    final details = context.read<ProductDetailsCubit>().state.product;    return Container(      color: AppColors.backgroundColor.withAlpha(220),      padding:          EdgeInsets.symmetric(horizontal: AppConfig.customPaddingFromRightLeft)              .r,      margin: EdgeInsets.only(bottom: 5).r,      child: Row(        mainAxisAlignment: MainAxisAlignment.spaceBetween,        children: [          RichText(            text: TextSpan(              children: [                TextSpan(                  text: "\$",                  style: AppTextStyles.h3Bold.copyWith(                    color: AppColors.primaryColor,                  ),                ),                TextSpan(                  text: details?.price.toString().split(".00").first,                  style: AppTextStyles.h3Bold.copyWith(                    color: AppColors.textColorBlack,                  ),                ),              ],            ),          ),          BuildSocialLoginButton(            size: Size(179.w, 56.h),            text: "Add Cart",            textStyle:                AppTextStyles.h5Bold.copyWith(color: AppColors.textColorWhite),            isSpace: false,            backgroundColor: AppColors.primaryColor,            onPressed: () {},          )        ],      ),    );  }}